import { NextResponse } from 'next/server'
import type { NextRequest } from 'next/server'

// Renamed from `middleware` to `proxy` in Next.js 16.
// Runs on the server before a request is completed.
export function proxy(request: NextRequest) {
  // Log the request pathname to the console.
  console.log(request.nextUrl.pathname)

  // Generate a unique value for the request id.
  const requestId = crypto.randomUUID()

  // Add the custom header to the response.
  const response = NextResponse.next()
  response.headers.set('X-Request-Id', requestId)

  return response
}

export const config = {
  // Run on all request paths except Next.js internals and common static assets.
  matcher: [
    '/((?!_next/static|_next/image|favicon.ico|sitemap.xml|robots.txt).*)',
  ],
}

